"use strict";
/*
 * Runs inside VSCode's built-in Markdown preview webview.
 * - Renders mermaid diagram blocks (.mermaid emitted by the mermaid
 *   markdown-it plugin, both fenced ```mermaid -> <pre class="mermaid"> and
 *   :::mermaid containers -> <div class="mermaid">) exactly like the built-in
 *   preview: colours are derived from the active VS Code theme via
 *   mermaid.initialize({ theme: 'base', themeVariables: ... }).
 * - Keeps support for `.commonmark-diagram` blocks generated by markdownItPlugins.
 * - Applies the selected CommonMark theme.
 */
(function () {
  let mermaidSeq = 0;
  let lastThemeFingerprint = "";

  // Disable mermaid's automatic run() on DOMContentLoaded (default
  // startOnLoad=true would render every .mermaid block with the default theme
  // before we have applied the VS Code theme variables). Rendering is driven
  // by renderMermaid() instead.
  if (typeof mermaid !== "undefined") {
    mermaid.initialize({ startOnLoad: false });
  }

  // ---- VS Code theme -> mermaid themeVariables (port of the built-in
  // mermaid-markdown-features preview-src/shared/vsCodeTheme.ts) ----
  function isDarkVsCodeTheme() {
    return document.body.classList.contains("vscode-dark")
      || (document.body.classList.contains("vscode-high-contrast") && !document.body.classList.contains("vscode-high-contrast-light"));
  }

  function rgbStringToHex(value) {
    const match = value.match(/^rgba?\(\s*(\d+)\s*,\s*(\d+)\s*,\s*(\d+)\s*(?:,\s*([\d.]+)\s*)?\)$/);
    if (!match) {
      return undefined;
    }
    const r = parseInt(match[1], 10);
    const g = parseInt(match[2], 10);
    const b = parseInt(match[3], 10);
    const a = match[4] !== undefined ? Math.round(parseFloat(match[4]) * 255) : 255;
    const hex = (n) => Math.max(0, Math.min(255, n)).toString(16).padStart(2, "0");
    return a < 255
      ? "#" + hex(r) + hex(g) + hex(b) + hex(a)
      : "#" + hex(r) + hex(g) + hex(b);
  }

  // Single reusable probe element. It is appended to <body> once and kept
  // there: re-appending/removing a probe on every theme computation would
  // trigger this file's MutationObserver and cause an infinite re-render loop.
  let cssProbe = null;

  function resolveCssColor(cssValue) {
    if (!cssProbe) {
      cssProbe = document.createElement("span");
      cssProbe.style.display = "none";
      document.body.appendChild(cssProbe);
    }
    cssProbe.style.color = cssValue;
    return rgbStringToHex(getComputedStyle(cssProbe).color);
  }

  function readCssVar(name) {
    return getComputedStyle(document.documentElement).getPropertyValue(name).trim();
  }

  function pickColor() {
    for (let i = 0; i < arguments.length; i++) {
      const name = arguments[i];
      if (!readCssVar(name)) {
        continue;
      }
      const hex = resolveCssColor("var(" + name + ")");
      if (hex) {
        return hex;
      }
    }
    return undefined;
  }

  function computeVsCodeMermaidThemeVariables() {
    const variables = { darkMode: isDarkVsCodeTheme() };
    function set(key) {
      const args = Array.prototype.slice.call(arguments, 1);
      const color = pickColor.apply(null, args);
      if (color) {
        variables[key] = color;
      }
    }

    set("background", "--vscode-editor-background");
    set("textColor", "--vscode-charts-foreground", "--vscode-editor-foreground", "--vscode-foreground");
    set("lineColor", "--vscode-chart-line", "--vscode-charts-lines", "--vscode-editor-foreground", "--vscode-foreground");

    set("primaryColor", "--vscode-editorWidget-background");
    set("primaryTextColor", "--vscode-charts-foreground", "--vscode-editor-foreground", "--vscode-foreground");
    set("primaryBorderColor", "--vscode-chart-line", "--vscode-editorWidget-border", "--vscode-focusBorder");
    set("mainBkg", "--vscode-editorWidget-background");
    set("nodeBorder", "--vscode-chart-line", "--vscode-editorWidget-border", "--vscode-focusBorder");

    set("secondaryColor", "--vscode-input-background", "--vscode-editorWidget-background");
    set("secondaryTextColor", "--vscode-input-foreground", "--vscode-foreground");
    set("secondaryBorderColor", "--vscode-input-border", "--vscode-editorWidget-border");

    set("tertiaryColor", "--vscode-textBlockQuote-background", "--vscode-input-background");
    set("tertiaryTextColor", "--vscode-foreground");
    set("tertiaryBorderColor", "--vscode-textBlockQuote-border", "--vscode-editorWidget-border");
    set("clusterBkg", "--vscode-textBlockQuote-background", "--vscode-input-background");
    set("clusterBorder", "--vscode-textBlockQuote-border", "--vscode-editorWidget-border");

    set("noteBkgColor", "--vscode-textBlockQuote-background", "--vscode-editorWidget-background");
    set("noteTextColor", "--vscode-foreground");
    set("noteBorderColor", "--vscode-textBlockQuote-border", "--vscode-editorWidget-border");

    set("errorBkgColor", "--vscode-inputValidation-errorBackground", "--vscode-editorError-background");
    set("errorTextColor", "--vscode-editorError-foreground", "--vscode-foreground");

    set("titleColor", "--vscode-charts-foreground", "--vscode-editor-foreground", "--vscode-foreground");
    set("edgeLabelBackground", "--vscode-editor-background");

    const chartPalette = [
      "--vscode-charts-blue",
      "--vscode-charts-green",
      "--vscode-charts-orange",
      "--vscode-charts-red",
      "--vscode-charts-purple",
      "--vscode-charts-yellow",
    ];
    for (let i = 0; i < chartPalette.length; i++) {
      set("pie" + (i + 1), chartPalette[i]);
      set("cScale" + i, chartPalette[i]);
    }

    const fontFamily = readCssVar("--vscode-font-family");
    if (fontFamily) {
      variables.fontFamily = fontFamily;
    }
    const fontSize = readCssVar("--vscode-font-size");
    if (fontSize) {
      variables.fontSize = fontSize;
    }
    return variables;
  }

  function getMermaidErrorMessage(error) {
    if (error instanceof Error) {
      return error.message;
    }
    if (error && typeof error === "object") {
      const candidate = error;
      if (typeof candidate.message === "string" && candidate.message) {
        return candidate.message;
      }
      if (typeof candidate.str === "string" && candidate.str) {
        return candidate.str;
      }
    }
    return String(error);
  }

  // Reference: VS Code built-in mermaid-markdown-features renders every
  // `.mermaid` element (fenced ```mermaid -> <pre class="mermaid">, or the
  // :::mermaid container -> <div class="mermaid">) with
  // mermaid.initialize({ theme: 'base', themeVariables }) and replaces the
  // element content with the produced SVG (shared/index.ts
  // renderMermaidBlocksInElement + renderMermaidElement).
  function renderMermaid(root) {
    if (typeof mermaid === "undefined") {
      return;
    }

    const themeVariables = computeVsCodeMermaidThemeVariables();
    const fingerprint = JSON.stringify(themeVariables);
    const themeChanged = fingerprint !== lastThemeFingerprint;
    lastThemeFingerprint = fingerprint;

    // Only re-initialize mermaid when the theme actually changed: initialize()
    // is expensive and would otherwise run on every render message.
    if (themeChanged) {
      mermaid.initialize({ startOnLoad: false, theme: "base", themeVariables });
    }

    const scope = root || document;
    const tasks = [];

    const renderOne = (container) => {
      const source = (container.textContent || "").trim();
      if (!source) {
        return;
      }
      if (container.dataset.source === source && container.querySelector("svg")) {
        return;
      }
      container.dataset.source = source;
      container.dataset.rendered = "true";
      const id = "mermaid-" + (mermaidSeq++);
      // render() parses internally, so an extra parse() would just double the
      // parsing work for every diagram (the built-in pays that cost).
      tasks.push(mermaid.render(id, source).then((result) => {
        container.innerHTML = result.svg;
        // Bind click/tooltip handlers like the built-in renderer does.
        if (typeof result.bindFunctions === "function") {
          result.bindFunctions(container);
        }
      }).catch((error) => {
        // Allow the next render message to retry this diagram.
        container.dataset.rendered = "false";
        const pre = document.createElement("pre");
        pre.className = "mermaid-error";
        const message = getMermaidErrorMessage(error);
        pre.textContent = message.length > 2000 ? message.slice(0, 2000) + "\n..." : message;
        container.innerHTML = "";
        container.appendChild(pre);
      }));
    };

    // Re-render every diagram when the theme changed so colours follow the
    // VS Code theme (sources are still in dataset.source after first render).
    if (themeChanged) {
      scope.querySelectorAll(".mermaid[data-rendered=\"true\"]").forEach((el) => {
        el.innerHTML = "";
        if (el.dataset.source) {
          el.textContent = el.dataset.source;
        }
        el.dataset.rendered = "false";
      });
    }

    // Keep the original parallel rendering: serializing all diagrams made the
    // first paint noticeably slower for documents with many diagrams.
    scope.querySelectorAll(".mermaid:not([data-rendered=\"true\"])").forEach((container) => {
      renderOne(container);
    });

    return Promise.all(tasks).catch(() => {});
  }

  // message pump for diagram rendering triggered from extension host
  function renderDiagrams(root) {
    renderMermaid(root);

    const blocks = (root || document).querySelectorAll(".commonmark-diagram");
    if (!blocks.length || typeof mermaid === "undefined") {
      return;
    }
    blocks.forEach((block) => {
      const src = block.querySelector(".mermaid-source");
      if (!src || block.dataset.rendered === "true") return;
      const code = src.textContent.trim();
      if (!code) return;
      const lang = block.dataset.lang || "mermaid";
      try {
        if (typeof mermaid !== "undefined") {
          const el = document.createElement("div");
          el.className = "mermaid";
          el.textContent = code;
          block.appendChild(el);
          mermaid.initialize({ startOnLoad: false, theme: "base", securityLevel: "loose", themeVariables: computeVsCodeMermaidThemeVariables() });
          mermaid.parseError = function () {};
          mermaid.run({ nodes: [el] }).then(() => {
            block.dataset.rendered = "true";
          }).catch(() => {
            block.innerHTML = `<pre class="hljs"><code class="language-${lang}">${code.replace(/</g, "&lt;")}</code></pre>`;
            block.dataset.rendered = "true";
          });
        }
      } catch (e) {
        block.innerHTML = `<pre><code>${code.replace(/</g, "&lt;")}</code></pre>`;
        block.dataset.rendered = "true";
      }
    });
  }

  // Listen for theme change messages from the extension host
  window.addEventListener("message", (event) => {
    const msg = event.data;
    if (msg && msg.type === "commonmark-theme") {
      setTheme(msg.theme);
      renderDiagrams(document);
    }
  });

  function setTheme(theme) {
    document.body.dataset.commonmarkTheme = theme || "github";
  }

  // initial render
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", () => renderDiagrams(document));
  } else {
    renderDiagrams(document);
  }

  // Observe DOM changes for newly added content
  const observer = new MutationObserver(() => renderDiagrams(document));
  observer.observe(document.body, { childList: true, subtree: true });

  // expose
  window.__commonmarkRender = renderDiagrams;
})();
